onClick:
{{
  (async () => {
    if (!Date_Corr.formattedDate) {
      showAlert('Veuillez sélectionner une date.', 'warning');
      return;
    }
    if (!Inp_Corr_Matin.text && !Inp_Corr_DebPause.text && !Inp_Corr_FinPause.text && !Inp_Corr_Soir.text) {
      showAlert('Renseignez au moins une heure à corriger.', 'warning');
      return;
    }
    try {
      await Send_Demande_Correction.run();
      showAlert('✅ Demande de correction transmise !', 'success');
      await Get_Mes_Demandes.run();
      await storeValue('ecran', 'ACCUEIL');
    } catch (err) {
      showAlert('Erreur : ' + (err.message || err), 'error');
    }
  })()
}}
